"""Original fictional notes and relevance labels, frozen before any retrieval run."""
import hashlib,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]/'data';root.mkdir(exist_ok=True)
topics=[
('手机遗失处置','手机丢失后，先借用设备冻结手机卡，再在备用设备退出支付账户和聊天账户。清点重要账户，使用预存的恢复码。','设备失联准备','在另一台设备保存紧急联系人与账户恢复码。记录手机序列号，开启设备查找；手机遗失时按清单处理。','手机找不到了，怎样避免账号被别人使用？'),
('数据库事务','订单扣库存与写入订单放入同一个数据库事务，全部成功后提交。发生异常则回滚，避免库存减少却没有订单。','事务一致性检查','测试订单创建失败时库存是否恢复。事务用于保证一组写入的原子性，不能在中间步骤随意提交。','下单失败了怎么防止库存已经被扣掉？'),
('缓存更新','修改商品价格后，提交数据库事务再删除价格缓存。读取未命中时重新从数据库获取最新价格。','缓存失效排查','价格显示陈旧时，核对缓存键、过期时间和失效通知。缓存失效不是数据删除，原始记录仍保存在数据库。','商品改价了，页面为什么还显示旧价格？'),
('本地备份','每周将项目资料复制到移动硬盘，每月在另一位置保存一份。备份完成后抽取文件，确认能够恢复。','恢复演练','备份不是复制后就结束。使用空目录恢复一份项目，核对文件数量和校验值，记录恢复耗时。','如何确认备份的资料真能救回来？'),
('会议纪要','会议结束前确认负责人、截止日期和具体交付物。纪要按决定、待办、问题组织，发送后请负责人核对。','行动项追踪','每条会议行动项都包含唯一负责人和可检查的完成条件。下次会议从未完成事项开始跟进。','开会之后怎么防止大家忘记自己要做什么？'),
('代码评审','提交评审时说明问题、行为变化和测试结果。把无关格式调整放到其他提交，便于审阅实际差异。','小步提交','一次代码修改解决一个明确问题。给出触发条件、修改前后示例以及回归检查，帮助评审者判断影响。','怎样让同事更容易看懂这次代码修改？'),
('向量检索','向量把文本编码成数值表示，可以查找表达不同但语义相近的内容。文档与查询必须使用同一模型配置。','混合检索','关键词检索擅长精确词，向量检索补充近义表达。数据库内融合两路排名，兼顾专有名称与语义。','用不同说法寻找相同意思的笔记该用什么检索？'),
('中文分词','中文全文索引需要合理的分词设置。检索专有名词时检查索引中的切词，避免完整词被拆成不合适的片段。','全文索引更新','新增文档后刷新全文和向量索引，再检查可见性。写入成功不等于所有索引已经可用。','新文章已经写入，为何关键词还搜不到？'),
('慢查询排查','分析慢查询前记录实际 SQL 与参数，查看执行计划和扫描行数。先确认过滤条件有没有命中合适的索引。','索引选择','给高频筛选条件建立索引，再用实际查询比较扫描范围。索引增加会带来写入和存储成本。','数据库检索越来越慢，先检查什么？'),
('阅读清单','给待阅读的书添加状态与标签。标签用于主题归类，状态用于区分未读、在读和已读，两者可以组合筛选。','书目筛选规则','按标签筛选使用完整标签匹配。查询数据库标签时，不应误匹配数据库索引这个更长的标签。','怎么只找已读且属于数据库主题的书？'),
('模型精度比较','比较 FP32 与 INT8 模型时，固定设备、语料、查询和后端。记录实际文件大小及检索指标，不凭感觉评价量化质量。','实验条件控制','一次实验尽量只改变一个因素。后端与精度同时改变时，结果只能说明联合配置差异。','如何公平比较模型量化前后的效果？'),
('浏览器本地推理','模型下载到浏览器后由本机执行推理。网页显示实际后端，运行环境没有 WebGPU 时使用 WASM 继续工作。','离线运行检查','关闭外部网络后测试已下载模型的导入与查询。保留网络请求记录，核对没有云端推理地址。','没有显卡加速时网页里的模型还能运行吗？'),
('环境锁定','使用依赖锁文件固定运行版本。新项目建立独立虚拟环境，记录 Python、Node 和数据库版本，避免破坏旧环境。','干净启动','从空数据目录重新安装依赖并执行说明中的命令。检查运行是否依赖机器上的私有文件或隐藏缓存。','怎样保证别人拿到项目也能运行？'),
('密码管理','项目演示使用占位配置示例，真实密钥仅存本地忽略文件。日志不打印认证头，也不把带密钥地址提交到仓库。','凭据检查','发布前检查暂存差异与忽略规则，确认配置文件没有进入版本控制。测试时只记录变量是否齐全。','开发密钥怎么避免被提交到公开仓库？'),
('资料版本','规格更新后保留旧版历史，并把新版标为当前有效。上下文查询先过滤有效版本，再选择相关规格与测试。','来源记录','每段工程上下文记录文件路径、版本、内容摘要和符号。这样能核对模型修改依据，避免使用过时要求。','需求改了以后怎么让开发助手拿到新规则？'),
('任务中断恢复','结束工作前保存已完成事项、失败测试与下一步。新进程先读取任务状态，跳过已完成导入，继续未完成的修改。','验证记录','保存测试命令、退出码、代码摘要和固定测试摘要。任务恢复后根据真实失败项选择后续处理。','程序重启后怎样继续上次没做完的开发？'),
('照片归档','按拍摄月份整理照片，保留原始文件与拍摄时间。挑选导出副本时不要覆盖原图，移动前核对目标目录。','重复文件处理','发现同名照片先比较内容摘要，不按文件名直接删除。把疑似重复项移到待核对目录，确认后再处理。','照片名字一样，如何判断是不是同一张？'),
('通勤计划','给虚构工作日记录三条通勤路线的步行时间与换乘次数。下雨时优先考虑步行较少的路线，出门前复核安排。','出行清单','前一晚准备门卡、雨伞和充电设备。临时改变路线时，重新检查目的地与换乘点，避免沿用旧计划。','下雨去上班想少走路，怎么安排？'),
('演讲排练','把汇报内容分为问题、方法、证据和结论。排练时逐页计时，把细节放入备份页，保留提问时间。','幻灯片取舍','一页围绕一个判断组织内容。图表要能支撑标题，字体保证后排可读，避免把整篇讲稿堆到页面上。','汇报超时又字太多，应该怎样调整？'),
('实验原始数据','保留未经修改的测量记录，处理结果另存新文件。缺失值和异常值单独标注，不能悄悄改成理想结果。','统计汇总','重复测量保留所有样本，报告中位数并区分首次加载与热运行。不能只选最快的一次作为整体性能。','性能测试重复多次以后应该怎样汇总？'),
('烘焙记录','虚构面包实验记录面粉批次、发酵时长与烤箱档位。每次只改变一个步骤，比较成品照片和操作记录。','咖啡笔记','记录咖啡豆名称、研磨刻度和冲煮方式。不同杯子的感受仅作个人记录，不用于推断普遍效果。',None),
('植物观察','为窗边植物每周拍照，记录浇水日期与叶片变化。标注光照位置，方便回顾环境变化。','阳台整理','把园艺工具放在固定位置，用标签区分种子袋。清理桌面时保留正在进行的观察记录。',None),
('音乐练习','每天练习一小段乐句，先降低速度保持节拍，再逐步提升。把容易出错的小节单独记录。','乐谱整理','为曲目建立名称、难度和练习阶段标签。旧版指法与新版指法分别保存，避免混淆。',None),
('桌游收藏','为虚构桌游记录人数、预计时长与配件数量。活动结束后按清单检查卡牌与骰子。','聚会安排','邀请者提前说明集合地点与活动时长。准备两种人数规模的活动方案，参与人数变化时及时调整。',None),
('城市速写','速写练习先观察建筑比例与透视，再记录阴影。每次保留日期与地点，比较不同天气的画面。','展览手记','参观虚构展览时记录作品标题和自己的疑问。转述展签时注明出处，个人联想另行标注。',None)]
corpus=[];queries=[]
for i,(ta,a,tb,b,q) in enumerate(topics):
    ids=[]
    for j,(title,text) in enumerate([(ta,a),(tb,b)]):
        id=f'n{i*2+j+1:02d}';ids.append(id);corpus.append({'id':id,'title':title,'text':title+'。'+text,'source':'原创虚构中文笔记，CC0-1.0'})
    if q:queries.append({'id':f'q{i+1:02d}','text':q,'relevant_ids':ids})
for name,content in [('corpus.json',corpus),('queries.json',queries)]:
    (root/name).write_text(json.dumps(content,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
freeze={'frozen_before_retrieval':True,'license':'CC0-1.0','documents':len(corpus),'queries':len(queries),'k':5,'metric':'mean Recall@5; each query has two relevant documents','files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [root/'corpus.json',root/'queries.json']},'engineering_targets':{'recall_at_5_min':0.85,'max_absolute_drop':0.05},'not_official_thresholds':True}
(root/'frozen.json').write_text(json.dumps(freeze,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(freeze,ensure_ascii=False))
